function login(role='farmer',mode='login',name='',preserve=false){const previous=preserve?$('#login-form'):null;const draft={name:previous?.elements.namedItem('name')?.value||(preserve?$('#modal').dataset.authName:'')||name,email:previous?.elements.email?.value||'',password:previous?.elements.password?.value||'',phone:previous?.elements.phone?.value||''};name=draft.name;chosenRole=role;authMode=mode;openModal(t(mode==='login'?'welcomeBack':'join'),`<div class="auth-layout"><aside class="auth-aside"><span class="auth-symbol">${icon('leaf')}</span><h3>${t('authSideTitle')}</h3><p>${t('authSideText')}</p><div class="auth-produce">${art('tomato')}</div><small>${t('homeTagline')}</small></aside><div class="auth-form"><div class="auth-tabs">${['login','register'].map(m=>`<button type="button" data-action="authMode" data-id="${m}" aria-pressed="${mode===m}" class="${mode===m?'selected':''}">${t(m)}</button>`).join('')}</div>${mode==='register'?`<p class="role-prompt">${t('rolePrompt')}</p><div class="role-grid">${['farmer','buyer'].map(r=>`<button type="button" data-action="chooseRole" data-id="${r}" aria-pressed="${r===role}" class="role-btn ${r===role?'selected':''}">${icon(r==='farmer'?'leaf':'bag')}${t(r)}</button>`).join('')}</div>`:''}<form id="login-form">${mode==='register'?`<label>${t('name')}<input name="name" maxlength="60" required value="${esc(name)}" autocomplete="name" placeholder="${t('enterName')}"></label>`:''}<label>${t('email')}<input name="email" type="email" required maxlength="254" autocomplete="username" placeholder="name@gmail.com" pattern="[A-Za-z0-9]+(?:[._\\-][A-Za-z0-9]+)*@(?:[Gg][Mm][Aa][Ii][Ll]\\.[Cc][Oo][Mm]|[Ss][Rr][Mm][Aa][Pp]\\.[Ee][Dd][Uu]\\.[Ii][Nn])" spellcheck="false" autocapitalize="none"></label><p class="small-note">${t('emailHint')}</p>${phoneField(draft.phone)}<p class="small-note">${t('contactNote')}</p><label>${t('password')}<span class="password-field"><input id="auth-password" aria-label="${t('password')}" name="password" type="password" required minlength="${mode==='register'?10:1}" maxlength="128" autocomplete="${mode==='register'?'new-password':'current-password'}" placeholder="${t('enterPassword')}"><button type="button" class="password-toggle" data-action="togglePassword" aria-controls="auth-password" aria-pressed="false">${t('showPassword')}</button></span></label>${mode==='register'?`<p class="small-note">${t('passwordHint')}</p>`:''}<p class="error" id="form-error" role="alert"></p><button class="btn full-width" type="submit">${t(mode==='login'?'signIn':'createAccount')}${icon('arrow')}</button></form><p class="auth-notice">${t('authNotice')}</p>${link('market',t('exploreFirst'),'auth-browse')}</div></div>`,'auth-modal');$('#modal').dataset.authName=draft.name;const form=$('#login-form');form.elements.email.value=draft.email;form.elements.password.value=draft.password}
function phoneField(value=''){return `<label>${t('phone')}<input name="phone" type="tel" inputmode="tel" autocomplete="tel" required maxlength="18" pattern="(?:[+]91[ ]?)?[6-9][0-9]{9}" placeholder="9876543210" value="${esc(value)}"></label>`}
function contactLine(phone){return phone?`<p class="contact-line"><span>${t('phone')}</span><a href="tel:+91${esc(phone)}">+91 ${esc(phone)}</a></p>`:''}
function accountContact(){return `<section class="account-contact"><div><strong>${t('contactDetails')}</strong><p>${esc(session.email)}</p>${contactLine(session.phone)||`<p>${t('enterPhone')}</p>`}</div>${action('editContact',t('editContact'),'btn secondary small')}</section>`}
function editContact(){openModal(t('contactDetails'),`<form id="contact-form">${phoneField(session?.phone)}<p class="small-note">${t('contactNote')}</p><p id="form-error" class="error" role="alert"></p><button type="submit" class="btn">${t('save')}</button></form>`)}
function details(id){const c=state.crops.find(c=>c.id===id);if(!c)return;openModal(cropName(c),`<div class="crop-art detail-art">${cropVisual(c)}</div><p>${esc(c.owner)} · ${esc(c.place)}</p>${trustBadge(c)}${qualityBadge(c)}${cropDates(c)}${contactLine(c.contactPhone)}<div class="money-row"><span>${t('price')}</span><strong>${money(c.price)}</strong></div><div class="money-row"><span>${t('quantity')}</span><strong>${c.qty} kg</strong></div>${c.description?`<p>${esc(c.description)}</p>`:''}<div class="form-actions">${c.sample?`<p class="small-note">${t('sampleOnly')}</p>`:c.mine?action('edit',t('edit'),'btn',c.id):c.archived||c.qty===0?`<p>${t('soldOut')}</p>`:action('offer',t('sendOffer')+icon('arrow'),'btn',c.id)}</div>`)}
function addCrop(id=''){if(session?.role!=='farmer')return toast(t('farmerOnly'));if(!session.phone)return editContact();const c=state.crops.find(c=>c.id===id&&c.mine);cropDraftPhoto='';openModal(t(c?'edit':'add'),`<form id="crop-form" data-id="${c?.id||''}" data-revision="${c?.revision||0}">${contactLine(session.phone)}<div class="form-grid"><label>${t('cropType')}<select name="kind" id="crop-kind">${['other','tomato','rice','chilli','mango','onion','potato','banana','brinjal'].map(k=>`<option value="${k}" ${(c?.kind||'other')===k?'selected':''}>${t(k)}</option>`).join('')}</select></label><label>${t('category')}<select name="category" id="crop-category">${['vegetables','grains','fruits'].map(k=>`<option value="${k}" ${c?.category===k?'selected':''}>${t(k)}</option>`).join('')}</select></label><label class="full">${t('cropName')}<input name="name" required maxlength="70" value="${esc(c?.name||'')}"></label><label>${t('quantity')}<input name="qty" type="number" min="${c?0:1}" max="1000000" step="1" required value="${c?.qty??''}"></label><label>${t('price')}<input name="price" type="number" min="0.01" max="100000" step="0.01" required value="${c?.price??''}"></label><div class="full quality-input"><label for="crop-quality">${t('quality')} <output id="quality-value" for="crop-quality">${c?.quality??75}</output><span>/100</span></label><input id="crop-quality" name="quality" type="range" min="0" max="100" step="1" value="${c?.quality??75}" aria-describedby="quality-help"><div class="quality-scale"><span>0</span><span>50</span><span>100</span></div><p id="quality-help" class="small-note">${t('qualityDeclaredNote')}</p></div><label>${t('cultivatedDate')}<input id="cultivated-date" name="cultivatedDate" type="date" min="1900-01-01" max="${new Date(Date.now()+330*60000).toISOString().slice(0,10)}" required value="${esc(c?.cultivated_date||'')}"></label><label>${t('harvestedDate')}<input id="harvested-date" name="harvestedDate" type="date" min="${esc(c?.cultivated_date||'1900-01-01')}" max="${new Date(Date.now()+330*60000).toISOString().slice(0,10)}" required value="${esc(c?.harvested_date||'')}"></label><label class="full">${t('location')}<input name="place" required maxlength="100" value="${esc(c?.place||'')}"></label><label class="full">${t('description')}<textarea name="description" rows="2" maxlength="500">${esc(c?.description||'')}</textarea></label><div class="full"><label>${t('cropPhoto')}<input type="file" id="listing-photo" accept="image/jpeg,image/png,image/webp"></label><p class="small-note">${t('photoHint')}</p><div class="listing-preview" id="listing-preview">${cropVisual(c||{kind:'other',name:''})}</div>${c?.image?`<label class="check-label"><input type="checkbox" name="removePhoto"> ${t('removePhoto')}</label>`:''}</div></div><p id="form-error" class="error" role="alert"></p><div class="form-actions">${action('close',t('cancel'),'btn secondary')}<button type="submit" class="btn">${t('save')}</button></div></form>`)}
function offerForm(id,order=false){const c=state.crops.find(c=>c.id===id);if(!session)return login('buyer');if(session.role!=='buyer')return toast(t('buyerOnly'));if(!session.phone)return editContact();if(!c||c.sample||c.archived||c.qty<1)return;if(state.offers.some(o=>o.crop===id&&o.status==='pending'))return toast(t('pendingOffer'));openModal(t(order?'orderRequest':'negotiatePrice'),`${order?`<p class="small-note">${t('orderRequestNote')}</p>`:''}<p>${cropName(c)} · ${c.qty} kg ${t('available')}</p><form id="offer-form" data-crop="${id}">${contactLine(session.phone)}<p class="small-note">${t('contactNote')}</p><div class="form-grid"><label>${t('offerQty')}<input name="qty" type="number" min="1" max="${c.qty}" step="1" value="${c.qty}" required></label><label>${t('offerPrice')}<input name="price" type="number" min="0.01" max="100000" step="0.01" value="${c.price}" ${order?'readonly':''} required></label><label>${t('transport')} (₹)<input name="transport" type="number" min="0" max="10000000" step="0.01" value="0" required></label><label>${t('handling')} (₹)<input name="handling" type="number" min="0" max="10000000" step="0.01" value="0" required></label></div><p class="small-note">${t('offerNote')}</p><div id="offer-preview">${breakdown({qty:c.qty,price:c.price,transport:0,handling:0})}</div><p id="form-error" class="error" role="alert"></p><div class="form-actions">${action('close',t('cancel'),'btn secondary')}<button type="submit" class="btn">${t(order?'orderRequest':'submitOffer')}</button></div></form>`)}
function values(form){const d=Object.fromEntries(new FormData(form));for(const k of ['qty','price','transport','handling','quality','rating'])if(k in d)d[k]=Number(d[k]);return d}
for(const [l,v] of Object.entries({"en":{"connectionLocal":"Cannot connect to Mitti Setu. Open “Start Mitti Setu.cmd”, keep its window open, then try again.","connectionOffline":"You are offline. Reconnect to the internet, then try again. Your open form has been kept.","connectionCloud":"Cannot reach Mitti Setu right now. Check your connection and try again shortly.","requestTimeout":"This is taking longer than expected. Before retrying, refresh your dashboard to check whether your change was saved.","reviewOffer":"Review before accepting","remainingStock":"Stock left after acceptance","confirmAccept":"Confirm and accept","acceptExplanation":"Accepting reserves this quantity and reduces your available stock. Offers that exceed the stock left will be declined. Payment and pickup are arranged directly with the buyer.","offerChanged":"This offer has changed. Refresh your dashboard and try again."},"hi":{"connectionLocal":"मिट्टी सेतु से संपर्क नहीं हो रहा। “Start Mitti Setu.cmd” खोलें, उसकी विंडो खुली रखें और फिर कोशिश करें।","connectionOffline":"आप ऑफ़लाइन हैं। इंटरनेट से जुड़कर फिर कोशिश करें। खुला फ़ॉर्म सुरक्षित रखा गया है।","connectionCloud":"अभी मिट्टी सेतु से संपर्क नहीं हो रहा। अपना इंटरनेट जाँचें और थोड़ी देर बाद कोशिश करें।","requestTimeout":"इसमें समय लग रहा है। दोबारा कोशिश करने से पहले डैशबोर्ड ताज़ा करके देखें कि बदलाव सेव हुआ है या नहीं।","reviewOffer":"स्वीकार करने से पहले जाँचें","remainingStock":"स्वीकार करने के बाद बची मात्रा","confirmAccept":"पुष्टि करें और स्वीकार करें","acceptExplanation":"स्वीकार करने पर यह मात्रा आरक्षित होगी और उपलब्ध मात्रा घटेगी। बची मात्रा से बड़े प्रस्ताव अस्वीकार होंगे। भुगतान और उठाव खरीदार से सीधे तय करें।","offerChanged":"यह प्रस्ताव बदल गया है। डैशबोर्ड ताज़ा करके फिर कोशिश करें।"},"te":{"connectionLocal":"మట్టి సేతుకు కనెక్ట్ కాలేదు. “Start Mitti Setu.cmd” తెరిచి, ఆ విండోను తెరిచి ఉంచి మళ్లీ ప్రయత్నించండి.","connectionOffline":"మీరు ఆఫ్‌లైన్‌లో ఉన్నారు. ఇంటర్నెట్‌కు కనెక్ట్ అయి మళ్లీ ప్రయత్నించండి. తెరిచిన ఫారమ్ అలాగే ఉంది.","connectionCloud":"ప్రస్తుతం మట్టి సేతుకు కనెక్ట్ కాలేదు. మీ కనెక్షన్‌ను తనిఖీ చేసి కొద్దిసేపటి తర్వాత ప్రయత్నించండి.","requestTimeout":"సాధారణం కంటే ఎక్కువ సమయం పడుతోంది. మళ్లీ ప్రయత్నించే ముందు డాష్‌బోర్డ్‌ను రిఫ్రెష్ చేసి మార్పు సేవ్ అయిందో చూడండి.","reviewOffer":"అంగీకరించే ముందు సమీక్షించండి","remainingStock":"అంగీకరించిన తర్వాత మిగిలే పరిమాణం","confirmAccept":"నిర్ధారించి అంగీకరించండి","acceptExplanation":"అంగీకరిస్తే ఈ పరిమాణం రిజర్వ్ అవుతుంది, అందుబాటులో ఉన్న పరిమాణం తగ్గుతుంది. మిగిలిన పరిమాణం కంటే పెద్ద ఆఫర్లు తిరస్కరించబడతాయి. చెల్లింపు, పికప్ కొనుగోలుదారుతో నేరుగా నిర్ణయించండి.","offerChanged":"ఈ ఆఫర్ మారింది. డాష్‌బోర్డ్‌ను రిఫ్రెష్ చేసి మళ్లీ ప్రయత్నించండి."}}))Object.assign(copy[l],v);
function connectionMessage(){if(['localhost','127.0.0.1','[::1]'].includes(location.hostname))return t('connectionLocal');return t(navigator.onLine===false?'connectionOffline':'connectionCloud')}
function reviewOffer(id){const o=state.offers.find(o=>o.id===id),c=o&&state.crops.find(c=>c.id===o.crop);if(!o||!c||!c.mine||o.status!=='pending')return toast(t('offerChanged'));openModal(t('reviewOffer'),`<div class="accept-review"><p><strong>${cropName(c)}</strong> · ${esc(o.buyer)}</p><div class="money-row"><span>${t('quantity')}</span><strong>${o.qty} kg</strong></div>${breakdown(o)}<div class="money-row"><span>${t('remainingStock')}</span><strong>${Math.max(0,c.qty-o.qty)} kg</strong></div><p class="small-note">${t('acceptExplanation')}</p><p id="form-error" class="error" role="alert"></p><div class="form-actions">${action('close',t('cancel'),'btn secondary')}${action('confirmAccept',t('confirmAccept'),'btn',id)}</div></div>`);$('#modal [data-action="close"]').focus()}

document.addEventListener('click',async e=>{
 if(e.target.closest('.auth-browse'))$('#modal').close();
 if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return}
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
 try{
 if(a==='close')$('#modal').close();
 else if(a==='login')login(session?.role||'farmer');
 else if(a==='getStarted')login(id||'farmer','register');
 else if(a==='togglePassword'){const input=$('#auth-password');const visible=input.type==='password';input.type=visible?'text':'password';b.textContent=t(visible?'hidePassword':'showPassword');b.setAttribute('aria-pressed',String(visible));b.setAttribute('aria-controls','auth-password')}
 else if(a==='editContact')editContact();
 else if(a==='authMode')login(chosenRole,id,'',true);
 else if(a==='chooseRole')login(id,authMode,'',true);
 else if(a==='logout'){b.disabled=true;careRecord=null;careHistory=[];if(photo){URL.revokeObjectURL(photo);photo=''}await api('/api/logout','POST',{});session=null;loadedLanguage=false;await refresh(false);location.hash='home';render()}
 else if(a==='refresh'){b.disabled=true;await refresh()}
 else if(a==='farmer'){if(session?.role==='farmer')location.hash='farmer';else login('farmer',session?'register':'login')}
 else if(a==='details')details(id);
 else if(a==='add')addCrop();
 else if(a==='edit')addCrop(id);
 else if(a==='remove'){const c=state.crops.find(c=>c.id===id);if(c?.mine)openModal(t('removeTitle'),`<p>${cropName(c)}</p><p>${t('removeNote')}</p><p id="form-error" class="error" role="alert"></p><div class="form-actions">${action('close',t('cancel'),'btn secondary')}${action('confirmRemove',t('remove'),'btn danger',id)}</div>`)}
 else if(a==='confirmRemove'){b.disabled=true;const c=state.crops.find(c=>c.id===id);await api('/api/crops/'+id+'/archive','POST',{revision:c.revision});$('#modal').close();await refresh();toast(t('updated'))}
 else if(a==='qualityInfo')qualityInfo(id);
 else if(a==='trustInfo')trustInfo(id);
 else if(a==='rateSeller')reviewSeller(id);
 else if(a==='rateFarmer')rateFarmer(id);
 else if(a==='offer')offerForm(id);
 else if(a==='order')offerForm(id,true);
 else if(a==='filter'){category=id;render()}
 else if(a==='reset'){category='all';query='';render()}
 else if(a==='cropOffers'){selectedCrop=id;render();$('#offers-panel').scrollIntoView({behavior:'smooth',block:'start'})}
 else if(a==='accept')reviewOffer(id);
 else if(['confirmAccept','decline','withdraw'].includes(a)){b.disabled=true;await api('/api/offers/'+id+'/'+(a==='confirmAccept'?'accept':a),'POST',{});if(a==='confirmAccept')$('#modal').close();await refresh();toast(t(a==='confirmAccept'?'offerAccepted':'updated'))}
 else if(a==='guidedMode'){careMode='guided';render()}
 else if(a==='photoMode'){careMode='photo';render()}
 else if(a==='analysePhoto'){if(analysisBusy)return;if(!analysisImage){analysisError=t('noAnalysis');render();return}analysisBusy=true;analysisError='';render();try{analysisResult=await api('/api/care/analyse','POST',{image:analysisImage,language:lang})}catch(err){analysisError=err.message}finally{analysisBusy=false;render()}}
 else if(a==='printCare')window.print();
 else if(a==='careHistory'){const result=await api('/api/care/reports');careHistory=result.reports;openModal(t('savedReports'),careHistory.length?careHistory.map(r=>`<div class="history-row"><div><strong>${esc(r.crop)}</strong><small>${new Date(r.created).toLocaleDateString()} · ${copy[lang].careSymptoms[r.symptom]}</small></div>${action('openCare',t('viewCrop'),'btn small secondary',r.id)}</div>`).join(''):`<p>${t('noReports')}</p>`)}
 else if(a==='openCare'){careRecord=careHistory.find(r=>r.id===id);careMode='guided';if(photo){URL.revokeObjectURL(photo);photo=''}$('#modal').close();render()}
 else if(a==='downloadCare'){const r=careRecord;if(!r)return;const content=reportText(r);const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='mitti-setu-care-note.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 else if(a==='sampleReport'){report=true;render()}
 else if(a==='hideReport'){report=false;render()}
 }catch(err){const target=$('#modal').open?$('#form-error'):null;if(target)target.textContent=err.message;else toast(err.message);await refresh(false)}finally{if(b.isConnected)b.disabled=false}
});
document.addEventListener('invalid',e=>{const el=e.target;if(!el.closest('#login-form'))return;const message=el.validity.valueMissing?t(el.name==='name'?'enterName':el.name==='email'?'enterEmail':el.name==='phone'?'enterPhone':'enterPassword'):el.name==='email'?t('validEmail'):el.name==='phone'?t('enterPhone'):t('passwordHint');el.setCustomValidity(message)},true);
document.addEventListener('input',e=>{if(e.target.closest('#login-form'))e.target.setCustomValidity('');
 if(e.target.id==='crop-quality')$('#quality-value').textContent=e.target.value;
 if(e.target.id==='cultivated-date'&&$('#harvested-date'))$('#harvested-date').min=e.target.value||'1900-01-01';
 if(e.target.id==='search'){query=e.target.value;$('#market-results').innerHTML=marketCards()}
 if(e.target.closest('#offer-form')){const d=values($('#offer-form'));$('#offer-preview').innerHTML=breakdown(d);$('#form-error').textContent=net(d)<0?t('costWarning'):''}
});
document.addEventListener('change',async e=>{
 try{
 if(e.target.id==='language'){lang=e.target.value;try{localStorage.setItem('mitti-language',JSON.stringify(lang))}catch{}render();if(session)await api('/api/me','PATCH',{language:lang})}
 if(e.target.id==='sort'){sortOrder=e.target.value;$('#market-results').innerHTML=marketCards()}
 if(e.target.id==='offer-crop'){selectedCrop=e.target.value;render()}
 if(e.target.id==='crop-kind'){const kind=e.target.value,form=$('#crop-form');if(kind!=='other'){form.elements.name.value=t(kind);form.elements.category.value=kind==='rice'?'grains':['mango','banana'].includes(kind)?'fruits':'vegetables'}else form.elements.name.value='';if(!cropDraftPhoto)$('#listing-preview').innerHTML=cropVisual({kind,name:t(kind)})}
 if(e.target.name==='removePhoto'){const c=state.crops.find(c=>c.id===$('#crop-form').dataset.id);$('#listing-preview').innerHTML=cropVisual({...c,image:e.target.checked?null:c.image})}
 if(e.target.id==='listing-photo'){const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>1.5*1024*1024)throw new Error(t('photoHint'));const bitmap=await createImageBitmap(f);bitmap.close();cropDraftPhoto=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(f)});$('#listing-preview').innerHTML=`<img class="produce-photo" src="${cropDraftPhoto}" alt="${t('cropPhoto')}">`}
 if(e.target.id==='analysis-photo'){const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024)throw new Error(t('invalidFile'));const bm=await createImageBitmap(f),canvas=document.createElement('canvas'),ratio=Math.min(1,1400/Math.max(bm.width,bm.height));canvas.width=Math.round(bm.width*ratio);canvas.height=Math.round(bm.height*ratio);canvas.getContext('2d').drawImage(bm,0,0,canvas.width,canvas.height);bm.close();analysisImage=canvas.toDataURL('image/jpeg',.82);if(analysisImage.length>2800000)throw new Error(t('invalidFile'));if(photo)URL.revokeObjectURL(photo);photo=URL.createObjectURL(f);analysisResult=null;analysisError='';render()}
 if(e.target.id==='care-photo'||e.target.id==='crop-photo'){const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024){toast(t('invalidFile'));e.target.value='';return}const bitmap=await createImageBitmap(f);bitmap.close();if(photo)URL.revokeObjectURL(photo);photo=URL.createObjectURL(f);report=false;const form=$('#care-form');if(form){const d=new FormData(form);careRecord=null;document.querySelector('.upload img')?.remove();const img=document.createElement('img');img.src=photo;img.alt='Selected crop photo';document.querySelector('.upload').prepend(img)}else render()}
 }catch(err){const target=$('#form-error');if(target)target.textContent=err.message||t('invalidFile');else toast(err.message||t('invalidFile'));if(e.target.type==='file')e.target.value=''}
});
document.addEventListener('submit',async e=>{
 e.preventDefault();const f=e.target,d=values(f),button=f.querySelector('[type="submit"]');if(!button||button.disabled)return;
 const original=button.innerHTML;button.disabled=true;button.textContent=t('saving');if($('#form-error'))$('#form-error').textContent='';
 try{
 if(f.id==='care-form'){careRecord={crop:String(d.crop).trim(),symptom:Number(d.symptom),days:Number(d.days),notes:String(d.notes||''),urgent:d.urgent==='on',created:Date.now()};if(session){const saved=await api('/api/care/reports','POST',careRecord);Object.assign(careRecord,saved)}render();return}
 else if(f.id==='contact-form'){await api('/api/me','PATCH',{phone:d.phone});await refresh(false);$('#modal').close();render();toast(t('updated'))}
 else if(f.id==='login-form'){await api(authMode==='register'?'/api/register':'/api/login','POST',{...d,role:chosenRole,language:lang});loadedLanguage=false;await refresh(false);$('#modal').close();location.hash=session?.role||'home';render();toast(t('welcome'))}
 else if(f.id==='review-form'){await api('/api/sellers/'+f.dataset.seller+'/rating','POST',{rating:d.rating,comment:d.comment||''});$('#modal').close();await refresh();toast(t('reviewSaved'))}
 else if(f.id==='crop-form'){const data={...d,photo:cropDraftPhoto||undefined,removePhoto:d.removePhoto==='on',revision:Number(f.dataset.revision)};await api('/api/crops'+(f.dataset.id?'/'+f.dataset.id:''),f.dataset.id?'PATCH':'POST',data);cropDraftPhoto='';$('#modal').close();await refresh();toast(t('updated'))}
 else if(f.id==='offer-form'){await api('/api/offers','POST',{...d,crop:f.dataset.crop});$('#modal').close();await refresh(false);location.hash='buyer';render();toast(t('offerSaved'))}
 }catch(err){if($('#form-error'))$('#form-error').textContent=err.message;else toast(err.message)}
 finally{if(button.isConnected){button.disabled=false;button.innerHTML=original}}
});
window.addEventListener('hashchange',async()=>{if($('#modal').open)$('#modal').close();render();window.scrollTo(0,0);if(['market','farmer','buyer'].includes(route()))await refresh()});
$('#modal').addEventListener('click',e=>{if(e.target!==e.currentTarget)return;const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()});
$('#modal').addEventListener('close',()=>{const password=$('#auth-password');if(password)password.value='';delete $('#modal').dataset.authName});
window.addEventListener('beforeunload',()=>{if(photo)URL.revokeObjectURL(photo)});
